apply.studio_css:
/* Typography Studio · personality=warmth · pair=fraunces_manrope_food */
:root {
  --font-display: "Fraunces", Georgia, serif;
  --font-body: "Manrope", "Segoe UI", system-ui, sans-serif;
  --font-sans: "Manrope", "Segoe UI", system-ui, sans-serif;
  --type-body-lh: 1.7;
  --type-headline-lh: 1.12;
  --type-track-display: -0.02em;
  --type-track-body: 0.01em;
  --type-btn-weight: 600;
}
body {
  font-family: var(--font-body);
  font-weight: 400;
  line-height: var(--type-body-lh);
  letter-spacing: var(--type-track-body);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
body .hero h1,
body .hero .hero-title,
body h1,
body .page-title {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(2.2rem, 5vw, 3.6rem);
  line-height: var(--type-headline-lh);
  letter-spacing: var(--type-track-display);
}
body .section h2,
body h2 {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: clamp(1.45rem, 2.4vw, 2rem);
  line-height: 1.2;
  letter-spacing: var(--type-track-display);
}
body .btn,
body button.btn,
body a.btn {
  font-family: var(--font-body);
  font-weight: var(--type-btn-weight);
  letter-spacing: 0.02em;
}
@media (max-width: 720px) {
  body { line-height: 1.55; }
  body .hero h1,
  body .hero .hero-title,
  body h1 {
    font-size: clamp(1.85rem, 8vw, 2.4rem);
    letter-spacing: -0.015em;
  }
}

